    const atividade = banco
      .prepare('SELECT id, titulo, tipo, salaId, vagas, cancelada FROM atividades WHERE id = ?')
      .get(req.params.id);
    if (!atividade) {
      return res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Atividade inexistente.' });
    }
    const confirmadas = banco.prepare(
      "SELECT participanteId FROM inscricoes WHERE atividadeId = ? AND status = 'confirmada' GROUP BY participanteId",
    ).all(atividade.id);
    const semChance = confirmadas.filter((c) => c.participanteId).length === 0;
    res.json({ semChance, atividadeId: atividade.id, titulo: atividade.titulo });
  });

